 void RefreshBeoSummary(){if(!beoBatchReady)return;int chosen=jobs.Count(j=>j.Selected),eligible=jobs.Count(j=>j.Selected&&!(skipFinished.Checked&&j.State==JobState.Done));batchInfo.Text=jobs.Count+" file · "+chosen+" được chọn · "+jobs.Count(j=>j.State==JobState.Done)+" hoàn tất · "+jobs.Count(j=>j.State==JobState.NeedsReview)+" cần xem lại";beoBatchReports.Text=WorkflowChoice==1?"Báo cáo mỗi file: filename.voice-report.txt":"Báo cáo mỗi file: trước/sau + câu đã sửa Anh–Việt";runBatch.Text=busy?"ĐANG CHẠY":"CHẠY "+eligible+" FILE";runBatch.Enabled=!busy&&eligible>0;}
