 void RefreshBeoRows(){if(!beoBatchReady||!jobGrid.Columns.Contains("completion"))return;for(int i=0;i<jobs.Count&&i<jobGrid.Rows.Count;i++){var j=jobs[i];var row=jobGrid.Rows[i];row.Cells["completion"].Value=j.Progress.Read().Percent;row.Cells["eta"].Value=j.State==JobState.Running?j.Progress.Read().Eta:j.State==JobState.Done?"Đã xong":j.State==JobState.Queued?"Chờ tới lượt":"—";row.Cells["selected"].Value=j.Selected;row.Cells[5].Value=j.State==JobState.Running?j.Progress.Read().Phase:j.Error.Length>0?j.Error:j.State==JobState.Done?"WAV + SRT đã kiểm tra":j.State==JobState.TranslationIncomplete?"WAV đạt · bản dịch chưa đủ":j.State==JobState.NeedsReview?"Xem báo cáo; checkpoint đã giữ":j.Warning;row.DefaultCellStyle.BackColor=j.State==JobState.Failed||j.State==JobState.ImportFailed?CurrentBeoPalette.Error:j.State==JobState.NeedsReview||j.State==JobState.TranslationIncomplete?CurrentBeoPalette.Warning:CurrentBeoPalette.Surface;row.DefaultCellStyle.ForeColor=CurrentBeoPalette.Text;}RefreshBeoSummary();RefreshBeoSelected();}
 void ResizeBeoBatchColumns(){if(!beoBatchReady||!jobGrid.Columns.Contains("eta"))return;float k=beoAppearance==null?1:beoAppearance.Scale/100f;int w=jobGrid.ClientSize.Width;jobGrid.Columns[1].Width=Math.Max(110,(int)(w*.22));jobGrid.Columns["completion"].Width=(int)(100*k);jobGrid.Columns["eta"].Width=(int)(150*k);jobGrid.Columns[4].Width=(int)(130*k);jobGrid.Columns[5].Visible=w>800;jobGrid.Columns[1].AutoSizeMode=w<=800?DataGridViewAutoSizeColumnMode.Fill:DataGridViewAutoSizeColumnMode.None;}
 void RefreshBeoScriptColors(){if(beoPalette==null)return;for(int i=0;i<grid.Rows.Count&&i<cues.Count;i++){string s=cues[i].Status??"";grid.Rows[i].DefaultCellStyle.BackColor=s.StartsWith("QUÁ")||s.Contains("Thiếu ")||s.Contains("Dư ")?beoPalette.Error:beoPalette.Surface;grid.Rows[i].DefaultCellStyle.ForeColor=beoPalette.Text;}}
 void RefreshBeoAvailability(){if(!beoBatchReady)return;beoBatchStop.Enabled=busy;RefreshBeoSummary();if(!busy&&beoStudioProgress.Read().Running)beoStudioProgress.Finish(false);}
 void RefreshBeoProgress(){if(beoProgressLabel==null||beoClosing||IsDisposed||Disposing||tabs.IsDisposed||tabs.SelectedIndex<0||tabs.SelectedIndex>=tabs.Controls.Count)return;RefreshCreatorRows();if(tabs.SelectedTab==creatorPage){var chosen=creatorProjects.Where(j=>j.Selected).ToList();int cp=chosen.Count==0?0:(int)chosen.Average(j=>j.Progress.Read().Percent);progress.Value=cp;progress.Invalidate();beoProgressLabel.Text="Tiến độ gói clip · "+cp+"%";var running=chosen.FirstOrDefault(j=>j.State=="RUNNING");beoEtaLabel.Text=running==null?"Dự kiến xong: —":"Clip đang chạy: "+running.Progress.Read().Eta;return;}RefreshBeoRows();bool queue=tabs.SelectedTab==batchPage;var selected=(busy&&beoActiveJobs!=null?beoActiveJobs:jobs.Where(j=>j.Selected).ToList());int p=queue?(selected.Count==0?0:(int)selected.Average(j=>j.Progress.Read().Percent)):beoStudioProgress.Read().Percent;progress.Value=Math.Max(0,Math.Min(100,p));progress.Invalidate();beoProgressLabel.Text=(queue?"Tiến độ hàng đợi":"Tiến độ file")+" · "+p+"%";double? remaining=queue?RenderProgress.QueueRemaining(selected):beoStudioProgress.Read().RemainingSeconds;beoEtaLabel.Text="Dự kiến xong: "+(remaining.HasValue?"~"+RenderProgress.FinishTime(remaining.Value)+" · còn "+RenderProgress.Duration(remaining.Value):busy?"Đang ước lượng":"—");}
}}
